const ALL_WORDS = new Set();
for (const len of Object.keys(WORDS)) {
  for (const word of WORDS[len]) {
    ALL_WORDS.add(word.toLowerCase());
  }
}

// Comprehensive English dictionary for guess validation
// Accepts any real English word, not just the curated answer pool
const englishWords = require('an-array-of-english-words');
const VALID_GUESSES = new Set();
for (const word of englishWords) {
  if (/^[a-z]+$/.test(word)) {
    VALID_GUESSES.add(word);
  }
}
// Ensure all curated answer words are also valid guesses
for (const word of ALL_WORDS) {
  VALID_GUESSES.add(word);
}

// Get available word lengths
function getWordLengths() {
  return Object.keys(WORDS).map(Number).sort((a, b) => a - b);
}

// Get a random word, weighted towards 5-letter words
function getRandomWord() {
  const weights = { 3: 1, 4: 2, 5: 5, 6: 2, 7: 1 };
  const entries = [];
  for (const [len, wordList] of Object.entries(WORDS)) {
    const weight = weights[len] || 1;
    for (let i = 0; i < weight; i++) {
      entries.push(len);
    }
  }
  const chosenLen = entries[Math.floor(Math.random() * entries.length)];
  const wordList = WORDS[chosenLen];
  return wordList[Math.floor(Math.random() * wordList.length)];
}

// Check if a word is in our curated answer pool
function isValidWord(word) {
  return ALL_WORDS.has(word.toLowerCase());
}

// Check if a word is a real English word (comprehensive dictionary)
function isValidGuess(word) {
  return VALID_GUESSES.has(word.toLowerCase());
}

module.exports = { getRandomWord, isValidWord, isValidGuess, getWordLengths, WORDS };
